import { test } from 'node:test';
import assert from 'node:assert/strict';
import Typesense from 'typesense';
import { getConversationModelId } from '../modules/typesense.js';

// Conversation IDs are generated by Typesense as UUID v4. Reads/deletes must
// reject any other value before it reaches a filter and quote exact values so
// filter syntax cannot widen a cross-tenant read or delete.
test('conversation reads and deletes fail closed on injected filter syntax', async () => {
	const originalClient = Typesense.Client;
	const filters = [];
	Typesense.Client = class {
		collections() {
			return { documents: () => ({
				search: async (params) => { filters.push(params.filter_by); return { hits: [] }; },
				delete: async (params) => { filters.push(params.filter_by); return { num_deleted: 0 }; },
			}) };
		}
	};
	const ts = await import(`../modules/typesense.js?conversation-injection=${Date.now()}`);
	try {
		const hostId = 'aaaaaaaaaaaaaaaaaaaaaaaa';
		const userId = 'bbbbbbbbbbbbbbbbbbbbbbbb';
		const modelId = getConversationModelId(hostId, userId);
		const injections = [
			'none || model_id:!=none || conversation_id:=none',
			'none || model_id:!=`none',
			'none || model_id:!=[none',
			'none || model_id:!=none && (model_id:!=none || conversation_id:=none)',
		];
		for (const injection of injections) {
			await assert.rejects(ts.getConversationMessages(hostId, userId, injection), /Invalid conversation ID/);
			await assert.rejects(ts.deleteConversation(hostId, userId, injection), /Invalid conversation ID/);
		}
		assert.equal(filters.length, 0);

		const uuid = '123e4567-e89b-12d3-a456-426614174000';
		await ts.getConversationMessages(hostId, userId, uuid);
		assert.equal(filters[0], `conversation_id:=\`${uuid}\` && model_id:=\`${modelId}\``);
		await ts.deleteConversation(hostId, userId, uuid);
		assert.equal(filters[1], `conversation_id:=\`${uuid}\` && model_id:=\`${modelId}\``);
	} finally {
		Typesense.Client = originalClient;
	}
});